input.command:
cd /opt/bench/plugins/draftsman/skills/draftsman; WORK=/tmp/dm; cat > $WORK/view.json <<'EOF'
{
  "title": "Safelist and its direct relations",
  "focus": "Safelist",
  "hops": 1,
  "members": {"*": "none", "Safelist": "public", "Safelist.*": "all"},
  "groups": [
    {"name": "safety", "members": ["Safelist", "Cleaner", "Safelist.TagName", "Safelist.AttributeKey", "Safelist.AttributeValue", "Safelist.Protocol"]},
    {"name": "nodes", "members": ["Attribute", "Attributes", "Element"]}
  ]
}
EOF
python3 scripts/render.py $WORK/ir.json $WORK/view.json -o $WORK/diagram.mmd && scripts/validate.sh $WORK/diagram.mmd; echo rc=$?; cat $WORK/diagram.mmd; python3 scripts/summary.py $WORK/ir.json | grep -A5 -i unresolved

